#include <stdio.h>

int main() {
    int nums[] = {3, 5, 4, 8};
    int n = 4, target = 8;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (nums[i] + nums[j] == target) {
                printf("%d + %d = %d (indices %d, %d)\n", nums[i], nums[j], target, i, j);
            }
        }
    }
    return 0;
}
